"""Português — profetas (prophets_001 … prophets_150)."""

T = {
"prophets_001": ("Que profeta construiu a arca por ordem de Allah?", ["Nuh (Noé)", "Ibrahim (Abraão)", "Musa (Moisés)", "Yusuf (José)"], "Allah ordenou a Nuh que construísse a arca para salvar os crentes do dilúvio."),
"prophets_002": ("Que profeta foi lançado num fogo que Allah tornou frio e seguro para ele?", ["Ibrahim (Abraão)", "Nuh (Noé)", "Dawud (David)", "Ayyub (Jó)"], "Allah ordenou ao fogo que fosse frio e seguro para Ibrahim."),
"prophets_003": ("Que profeta foi engolido por um enorme peixe?", ["Yunus (Jonas)", "Ilyas (Elias)", "Idris (Enoque)", "Zakariyya (Zacarias)"], "Yunus foi engolido pelo peixe depois de deixar o seu povo irado; Allah perdoou-o."),
"prophets_004": ("Que profeta interpretou o sonho do rei das sete vacas gordas e sete vacas magras?", ["Yusuf (José)", "Ya'qub (Jacó)", "Isma'il (Ismael)", "Ishaq (Isaac)"], "Yusuf interpretou o sonho do rei: sete anos de fartura seguidos de sete anos de fome."),
"prophets_005": ("Segundo o Alcorão, a que profeta Allah falou diretamente?", ["Musa (Moisés)", "Harun (Aarão)", "Yusuf (José)", "Sulaiman (Salomão)"], "O Alcorão afirma que Allah falou diretamente com Musa."),
"prophets_006": ("Que profeta compreendia a linguagem dos pássaros?", ["Sulaiman (Salomão)", "Dawud (David)", "Yunus (Jonas)", "Yusuf (José)"], "Allah ensinou a Sulaiman a linguagem dos pássaros."),
"prophets_007": ("A que profeta foi dada a escritura chamada Zabur (Salmos)?", ["Dawud (David)", "Musa (Moisés)", "Isa (Jesus)", "Ibrahim (Abraão)"], "O Alcorão menciona que o Zabur foi dado a Dawud."),
"prophets_008": ("Que profeta nasceu sem pai, pela palavra de Allah «Sê, e é»?", ["Isa (Jesus)", "Yahya (João)", "Isma'il (Ismael)", "Ishaq (Isaac)"], "O Alcorão descreve o nascimento milagroso de Isa sem pai, apenas pela palavra de Allah."),
"prophets_009": ("Que capítulo (surata) do Alcorão tem o nome da mãe de um profeta?", ["Maryam", "Yusuf", "Nuh", "Hud"], "A surata 19, Maryam, tem o nome da mãe do profeta Isa."),
"prophets_010": ("Que profeta foi provado com uma doença grave e é louvado pela sua paciência?", ["Ayyub (Jó)", "Zakariyya (Zacarias)", "Yahya (João)", "Idris (Enoque)"], "Ayyub manteve-se paciente numa prova muito dura, e Allah recompensou-o."),
"prophets_011": ("Perante quem Allah ordenou aos anjos que se prostrassem, em sinal de honra?", ["Adam", "Nuh (Noé)", "Ibrahim (Abraão)", "Musa (Moisés)"], "Allah ordenou aos anjos que se prostrassem perante Adam em sinal de honra, não de adoração."),
"prophets_012": ("Que profeta é chamado «Khalilullah», o amigo íntimo de Allah?", ["Ibrahim (Abraão)", "Musa (Moisés)", "Isa (Jesus)", "Muhammad ﷺ"], "O Alcorão descreve Ibrahim como o amigo íntimo (khalil) de Allah."),
"prophets_013": ("Que profeta foi lançado num poço pelos seus irmãos?", ["Yusuf (José)", "Bunyamin (Benjamim)", "Ya'qub (Jacó)", "Isma'il (Ismael)"], "Os irmãos de Yusuf lançaram-no num poço por inveja."),
"prophets_014": ("O povo de que profeta foi destruído por um dilúvio depois de o rejeitar?", ["Nuh (Noé)", "Hud", "Salih", "Shu'ayb"], "O povo de Nuh foi submerso pelo dilúvio depois de rejeitar obstinadamente a sua mensagem."),
"prophets_015": ("Que profeta viu o mar abrir-se para salvar o seu povo do Faraó?", ["Musa (Moisés)", "Harun (Aarão)", "Yusuf (José)", "Isma'il (Ismael)"], "Allah ordenou a Musa que golpeasse o mar, que se abriu para os crentes passarem."),
"prophets_016": ("Que profeta, com o seu pai Dawud, julgou o caso de um campo pastado por ovelhas?", ["Sulaiman (Salomão)", "Isma'il (Ismael)", "Yusuf (José)", "Ishaq (Isaac)"], "O Alcorão relata que Sulaiman e Dawud julgaram este caso, e Allah deu a Sulaiman o seu entendimento."),
"prophets_017": ("A mãe de quem foi instruída a colocar o seu bebé num rio?", ["Musa (Moisés)", "Isa (Jesus)", "Yusuf (José)", "Isma'il (Ismael)"], "Allah inspirou a mãe de Musa a colocá-lo numa arca sobre o rio para o proteger."),
"prophets_018": ("A camela de quem foi um sinal dado ao seu povo, os Thamud?", ["Salih", "Hud", "Shu'ayb", "Lut (Lot)"], "Allah enviou uma camela como sinal ao povo de Thamud através do profeta Salih."),
"prophets_019": ("A que profeta Allah ensinou os nomes de todas as coisas?", ["Adam", "Nuh (Noé)", "Ibrahim (Abraão)", "Musa (Moisés)"], "Allah ensinou a Adam os nomes de todas as coisas, e os anjos reconheceram a sabedoria de Allah."),
"prophets_020": ("Que profeta falou às pessoas ainda bebé, no berço?", ["Isa (Jesus)", "Yahya (João)", "Yusuf (José)", "Ismail (Ismael)"], "O bebé Isa falou do berço: «Sou o servo de Allah; Ele deu-me a Escritura»."),
"prophets_021": ("Com que filho Ibrahim ergueu os alicerces da Ka'ba?", ["Ismail (Ismael)", "Ishaq (Isaac)", "Yaqub (Jacó)", "Yusuf (José)"], "«E quando Ibrahim e Ismail erguiam os alicerces da Casa…»: construíram juntos."),
"prophets_022": ("Que filho foi anunciado ao profeta Zakariyya na sua velhice?", ["Yahya (João)", "Isa (Jesus)", "Ismail (Ismael)", "Ishaq (Isaac)"], "«Ó Zakariyya, anunciamos-te um menino cujo nome será Yahya.»"),
"prophets_023": ("Em que se transformou o cajado de Musa quando Allah lhe disse que o lançasse?", ["Numa serpente que se movia", "Num pássaro", "Numa fonte de água", "Numa luz"], "«Lança-o, ó Musa!» Ele lançou-o, e tornou-se uma serpente que se movia depressa."),
"prophets_024": ("No seu sonho, o que viu o jovem Yusuf prostrar-se diante dele?", ["Onze estrelas, o sol e a lua", "Sete vacas gordas", "Uma chuva de ouro", "Um jardim de palmeiras"], "Yusuf viu onze estrelas, o sol e a lua a prostrarem-se diante dele: um sinal do seu destino."),
"prophets_025": ("A que povo foi enviado o profeta Hud?", ["Aos 'Ad", "Aos Thamud", "Ao povo de Madyan", "Ao povo do Faraó"], "«E aos 'Ad, o seu irmão Hud…»: chamou-os a adorar apenas Allah."),
"prophets_026": ("A que povo foi enviado o profeta Shu'ayb?", ["Ao povo de Madyan", "Aos 'Ad", "Aos Thamud", "Ao povo de Nuh"], "«E a Madyan, o seu irmão Shu'ayb…»: ordenou-lhes que dessem medida e peso justos."),
"prophets_027": ("Que profeta é chamado «Dhun-Nun» (o do peixe) no Alcorão?", ["Yunus (Jonas)", "Musa (Moisés)", "Sulayman (Salomão)", "Ayyub (Jó)"], "«E Dhun-Nun, quando partiu irado…»: é Yunus, depois engolido pelo peixe."),
"prophets_028": ("Em que surata Musa viaja para aprender com um servo a quem Allah deu um conhecimento especial?", ["Al-Kahf (A Caverna)", "Yusuf", "Maryam", "An-Naml"], "Na surata Al-Kahf, Musa acompanha um servo sábio e aprende a ter paciência com o que ainda não compreende."),
"prophets_029": ("Que profeta é mencionado pelo nome mais vezes no Alcorão?", ["Musa (Moisés)", "Ibrahim (Abraão)", "Nuh (Noé)", "Isa (Jesus)"], "Musa é o profeta mais nomeado no Alcorão; a sua história com o Faraó volta muitas vezes."),
"prophets_030": ("Quantos profetas são mencionados pelo nome no Alcorão?", ["25", "10", "50", "99"], "Vinte e cinco profetas são nomeados no Alcorão, de Adam a Muhammad ﷺ."),
"prophets_031": ("Com a permissão de Allah, que profeta curou o cego e o leproso?", ["Isa (Jesus)", "Musa (Moisés)", "Dawud (David)", "Yunus (Jonas)"], "Isa curou o cego e o leproso com a permissão de Allah: um sinal para o seu povo."),
"prophets_032": ("Segundo o Alcorão, quanto tempo Nuh permaneceu entre o seu povo chamando-o a Allah?", ["950 anos", "100 anos", "300 anos", "40 anos"], "«Permaneceu entre eles mil anos menos cinquenta»: 950 anos de chamada paciente."),
"prophets_033": ("Segundo o Alcorão, de que criou Allah Adam?", ["De argila", "De luz", "De fogo", "De água"], "Allah disse aos anjos: «Vou criar um ser humano de argila»."),
"prophets_034": ("Quem tentou Adam e a sua esposa a comer da árvore proibida?", ["Shaytan (Iblis)", "Um anjo", "Um pássaro", "Um rei"], "Shaytan sussurrou-lhes para que comessem da árvore que Allah tinha proibido."),
"prophets_035": ("Que razão deu Iblis para se recusar a prostrar-se perante Adam?", ["«Sou melhor do que ele: criaste-me de fogo e a ele de argila»", "Não sabia quem era Adam", "Tinha medo dos anjos", "Estava a dormir"], "Iblis recusou por orgulho: «Criaste-me de fogo, e a ele criaste-o de argila»."),
"prophets_036": ("Depois da morte entre os dois filhos de Adam, que animal enviou Allah para mostrar como enterrar o corpo?", ["Um corvo", "Um cão", "Uma pomba", "Uma raposa"], "Allah enviou um corvo que escavou a terra para mostrar ao assassino como esconder o corpo do irmão."),
"prophets_037": ("O que diz o Alcorão sobre o profeta Idris?", ["Allah elevou-o a um lugar muito alto", "Construiu uma arca", "Foi engolido por um peixe", "Falou com as formigas"], "«E elevámo-lo a um lugar muito alto.»"),
"prophets_038": ("O que fez o filho de Nuh quando o pai o chamou para a arca?", ["Recusou e disse que se abrigaria numa montanha", "Embarcou primeiro", "Construiu a sua própria arca", "Foi reunir animais"], "Disse: «Refugiar-me-ei numa montanha»; as ondas cobriram-no."),
"prophets_039": ("Em que monte pousou a arca de Nuh, segundo o Alcorão?", ["No monte Judi", "No monte Sinai", "No monte Uhud", "No monte Arafat"], "«E a arca pousou sobre o Judi.»"),
"prophets_040": ("O que ordenou Allah a Nuh que carregasse na arca?", ["Um casal de cada espécie, e os crentes", "Apenas a sua família", "Apenas pássaros", "Ouro e prata"], "«Carrega nela um casal de cada espécie, e a tua família… e quem tiver crido.»"),
"prophets_041": ("O que fizeram os chefes do povo de Nuh ao vê-lo construir a arca?", ["Zombaram dele", "Ajudaram-no", "Trouxeram-lhe madeira", "Rezaram com ele"], "Sempre que chefes do seu povo passavam, zombavam dele."),
"prophets_042": ("Como descreve o Alcorão Nuh na surata Al-Isra?", ["Um servo agradecido", "Um rei poderoso", "Um grande viajante", "Um homem silencioso"], "«Na verdade, era um servo agradecido.»"),
"prophets_043": ("Como foi destruído o povo de 'Ad, ao qual Hud foi enviado?", ["Por um vento violento e furioso", "Por um dilúvio", "Por uma chuva de pedras", "Por um terramoto"], "«Quanto aos 'Ad, foram destruídos por um vento gélido e violento.»"),
"prophets_044": ("O que atingiu os Thamud, o povo de Salih?", ["Um grito terrível", "Um dilúvio", "Uma fome", "Uma praga de gafanhotos"], "«E o grito atingiu os que tinham sido injustos.»"),
"prophets_045": ("Qual é o nome do pai de Ibrahim mencionado no Alcorão?", ["Azar", "Tarih", "Lut", "Kan'an"], "«Ibrahim disse ao seu pai Azar: tomas ídolos por deuses?»"),
"prophets_046": ("Depois de partir os ídolos, qual deixou Ibrahim intacto?", ["O maior", "O mais pequeno", "O de ouro", "Nenhum, partiu-os todos"], "Fê-los em pedaços, exceto o maior, para que o seu povo o interrogasse."),
"prophets_047": ("Depois de ver a estrela, a lua e depois o sol pôr-se, o que declarou Ibrahim?", ["«Não amo os que se põem»", "«O sol é o meu senhor»", "«A lua é a mais bela»", "«Vou dormir»"], "À medida que cada um se punha, dizia: «Não amo os que se põem», e voltou-se para o Criador."),
"prophets_048": ("Quantas aves disse Allah a Ibrahim que tomasse, para lhe mostrar como dá vida aos mortos?", ["Quatro", "Duas", "Sete", "Doze"], "«Toma quatro aves… depois chama-as: virão a ti a toda a pressa.»"),
"prophets_049": ("O que serviu Ibrahim aos seus hóspedes, os anjos que traziam a boa nova?", ["Um vitelo assado", "Tâmaras", "Leite", "Pão e mel"], "«Não tardou em trazer um vitelo assado.»"),
"prophets_050": ("Que boa nova trouxeram os anjos à esposa de Ibrahim?", ["O nascimento de Ishaq", "Uma viagem", "Uma grande riqueza", "Chuva abundante"], "«Anunciámos-lhe Ishaq, e depois de Ishaq, Ya'qub.»"),
"prophets_051": ("Como reagiu o filho de Ibrahim quando o pai lhe contou o sonho de o sacrificar?", ["Aceitou: «Faz o que te é ordenado»", "Fugiu", "Chorou e recusou", "Escondeu-se"], "Disse: «Meu pai, faz o que te é ordenado». E Allah resgatou-o com um grande sacrifício."),
"prophets_052": ("Na sua oração, onde diz Ibrahim que instalou parte da sua família?", ["Num vale sem cultivo, junto à Casa Sagrada", "Junto ao Nilo", "Numa floresta", "Numa ilha"], "«Instalei parte da minha descendência num vale sem cultivo, junto à Tua Casa Sagrada.»"),
"prophets_053": ("O que pediu Ibrahim para a cidade de Meca na sua oração?", ["Que fosse uma cidade segura e o seu povo recebesse frutos", "Que se tornasse um reino", "Que chovesse sempre ali", "Que tivesse um rio"], "«Senhor meu, faz desta uma cidade segura e provê o seu povo de frutos.»"),
"prophets_054": ("Ao erguer a Ka'ba, Ibrahim e Isma'il pediram a Allah que enviasse entre os seus descendentes…", ["Um mensageiro de entre eles, que recitasse os Seus versículos", "Um rei", "Um exército", "Um tesouro"], "«Senhor nosso, envia entre eles um mensageiro deles mesmos que lhes recite os Teus versículos.»"),
"prophets_055": ("O Alcorão diz que um profeta foi, por si só, «uma nação (umma)». Qual?", ["Ibrahim", "Nuh", "Musa", "Sulayman"], "«Na verdade, Ibrahim era uma nação, devotamente obediente a Allah, reto.»"),
"prophets_056": ("Por que qualidade louva o Alcorão Isma'il na surata Maryam?", ["Era fiel à sua promessa", "Era muito rico", "Era um rei", "Sabia nadar"], "«Na verdade, era fiel à sua promessa, e era mensageiro e profeta.»"),
"prophets_057": ("Que castigo atingiu o povo de Lut?", ["Uma chuva de pedras de argila cozida", "Um dilúvio", "Uma praga de insetos", "Uma seca"], "«Virámos a cidade de pernas para o ar e fizemos chover sobre ela pedras de argila cozida.»"),
"prophets_058": ("As esposas de que dois profetas o Alcorão dá como exemplo de descrença?", ["Nuh e Lut", "Ibrahim e Musa", "Dawud e Sulayman", "Ayyub e Yunus"], "«Allah apresenta como exemplo dos descrentes a esposa de Nuh e a esposa de Lut.»"),
"prophets_059": ("Quem era o pai de Ya'qub?", ["Ishaq", "Isma'il", "Ibrahim", "Yusuf"], "Os anjos anunciaram à esposa de Ibrahim «Ishaq, e depois de Ishaq, Ya'qub»."),
"prophets_060": ("O que aconteceu à visão de Ya'qub de tanto chorar por Yusuf?", ["Os seus olhos ficaram brancos", "Via melhor à noite", "Nada mudou", "Perdeu um olho"], "«Os seus olhos ficaram brancos de tristeza, e ele continha-a.»"),
"prophets_061": ("O que devolveu a visão a Ya'qub?", ["A camisa de Yusuf lançada sobre o seu rosto", "Uma planta", "Água de Zamzam", "Um unguento"], "Yusuf disse: «Lançai a minha camisa sobre o rosto do meu pai; ele recuperará a visão»."),
"prophets_062": ("O que preferiu Yusuf em vez de ceder ao que lhe propunham indevidamente?", ["A prisão", "O exílio", "A riqueza", "O silêncio"], "«Senhor meu, a prisão é-me mais querida do que aquilo a que me convidam.»"),
"prophets_063": ("Na prisão, dois jovens contaram a Yusuf os seus sonhos. O que viu um deles?", ["Que espremia uvas", "Que voava", "Que guardava ovelhas", "Que cavava um poço"], "Um viu-se a espremer vinho; o outro, a levar pão na cabeça de que os pássaros comiam."),
"prophets_064": ("Quantos anos de fartura e depois de seca previu Yusuf ao rei?", ["Sete e sete", "Três e três", "Dez e dez", "Um e um"], "«Semeareis sete anos… depois virão sete anos difíceis.»"),
"prophets_065": ("Que cargo pediu Yusuf ao rei do Egito?", ["Os celeiros do país", "O comando do exército", "O trono", "O tesouro de ouro"], "«Põe-me à frente dos celeiros do país: sou um guardião sabedor.»"),
"prophets_066": ("O que mandou Yusuf pôr na bagagem do seu irmão mais novo para o manter a seu lado?", ["A taça do rei", "Um saco de ouro", "Uma carta", "A sua camisa"], "«Pôs a taça no saco do seu irmão.»"),
"prophets_067": ("Que conselho deu Ya'qub aos seus filhos antes de entrarem no Egito?", ["Entrar por portas diferentes", "Viajar de noite", "Disfarçar-se", "Levar presentes"], "«Não entreis por uma só porta, mas entrai por portas diferentes.»"),
"prophets_068": ("Porque foram os irmãos de Yusuf ao Egito quando ele governava ali?", ["Para obter provisões durante a fome", "Para o encontrar", "Para fazer peregrinação", "Para vender camelos"], "Os irmãos vieram buscar cereais; entraram diante dele e não o reconheceram."),
"prophets_069": ("Em que casa foi acolhido o bebé Musa depois de ser posto no rio?", ["Na do Faraó", "Na de um pastor", "Na de um pescador", "Na de um mercador"], "A família do Faraó recolheu-o, para que um dia fosse para eles inimigo e motivo de pesar."),
"prophets_070": ("Como voltou finalmente o bebé Musa para a sua mãe?", ["Recusou todas as amas e a sua irmã sugeriu a mãe", "O Faraó devolveu-o por piedade", "A mãe roubou-o de noite", "Um anjo levou-o"], "Allah fê-lo recusar as amas; a irmã sugeriu uma casa: era a da sua mãe, que o amamentou."),
"prophets_071": ("Porque teve Musa de deixar o Egito à pressa, antes da sua missão?", ["Tinha matado um homem sem querer, com um golpe", "Tinha roubado no palácio", "Recusou pagar impostos", "Tinha insultado o Faraó"], "Golpeou um egípcio que lutava com um homem do seu povo e matou-o; arrependeu-se de imediato."),
"prophets_072": ("Quem avisou Musa de que os chefes tramavam matá-lo?", ["Um homem que veio a correr do extremo da cidade", "A sua mãe", "Harun", "Um soldado"], "«Um homem veio a correr do extremo da cidade: conspiram para te matar, vai-te embora!»"),
"prophets_073": ("Ao chegar a Madyan, o que fez Musa por duas mulheres junto ao bebedouro?", ["Deu de beber ao seu rebanho", "Vendeu-lhes um camelo", "Construiu-lhes uma casa", "Ensinou-as a ler"], "Deu de beber ao rebanho delas e depois retirou-se para a sombra invocando Allah."),
"prophets_074": ("Quantos anos pediu o ancião de Madyan a Musa que trabalhasse para casar com a sua filha?", ["Oito, e dez se quisesse", "Um", "Quarenta", "Três"], "«Servir-me-ás oito anos; se completares dez, será por tua vontade.»"),
"prophets_075": ("O que ordenou Allah a Musa que tirasse no vale sagrado de Tuwa?", ["As sandálias", "O manto", "O cajado", "O turbante"], "«Tira as sandálias: estás no vale sagrado de Tuwa.»"),
"prophets_076": ("Qual foi o segundo sinal dado a Musa, depois do cajado?", ["A sua mão saiu branca, sem mal", "Podia voar", "A sua voz tornou-se trovão", "Via de noite"], "«Leva a mão ao teu lado: sairá branca, sem doença.»"),
"prophets_077": ("O que pediu Musa a Allah antes de ir ter com o Faraó?", ["Que lhe dilatasse o peito e lhe soltasse a língua", "Um exército", "Ouro", "Um cavalo veloz"], "«Senhor meu, dilata-me o peito, facilita a minha tarefa e desata o nó da minha língua.»"),
"prophets_078": ("Quem pediu Musa a Allah como ajudante na sua missão?", ["O seu irmão Harun", "O seu filho", "O seu sogro", "Um anjo"], "«Dá-me um ajudante da minha família: Harun, o meu irmão.»"),
"prophets_079": ("O que fizeram os magos do Faraó quando o cajado de Musa engoliu as suas ilusões?", ["Caíram prostrados e creram", "Fugiram", "Riram-se", "Atacaram Musa"], "Os magos caíram prostrados: «Cremos no Senhor dos mundos, o Senhor de Musa e Harun»."),
"prophets_080": ("Qual destas pragas o Alcorão enumera entre as enviadas contra o povo do Faraó?", ["Gafanhotos", "Neve", "Lobos", "Fogo"], "«Enviámos contra eles a inundação, os gafanhotos, os piolhos, as rãs e o sangue.»"),
"prophets_081": ("Segundo o Alcorão, o que fez Allah com o corpo do Faraó depois de se afogar?", ["Preservou-o como sinal", "Fê-lo desaparecer", "Queimou-o", "Devolveu-o ao seu povo"], "«Hoje salvaremos o teu corpo, para que sejas um sinal para os que vierem depois de ti.»"),
"prophets_082": ("Segundo o Alcorão, o que pediu a Allah a esposa crente do Faraó?", ["Uma casa junto d'Ele no Paraíso", "Um filho", "A morte do Faraó", "Um reino"], "«Senhor meu, constrói-me junto de Ti uma casa no Paraíso, e salva-me do Faraó.»"),
"prophets_083": ("Quantas noites durou o encontro marcado de Allah com Musa no monte?", ["Quarenta", "Sete", "Dez", "Cem"], "«Marcámos a Musa trinta noites e completámo-las com dez: quarenta noites.»"),
"prophets_084": ("O que aconteceu quando Musa pediu para ver Allah?", ["Allah manifestou-Se ao monte, que se desfez, e Musa caiu desmaiado", "Viu Allah", "Nada aconteceu", "O monte subiu ao céu"], "«Olha para o monte: se ficar no seu lugar, ver-Me-ás.» O monte foi pulverizado e Musa caiu desmaiado."),
"prophets_085": ("Em que escreveu Allah exortações e explicações para Musa?", ["Em Tábuas", "Em folhas de palmeira", "Numa pedra negra", "Em couro"], "«Escrevemos-lhe nas Tábuas uma exortação sobre todas as coisas.»"),
"prophets_086": ("Quem fez o bezerro que os Filhos de Israel adoraram na ausência de Musa?", ["As-Samiri", "Harun", "O Faraó", "Qarun"], "«As-Samiri desencaminhou-os»: dos seus adornos produziu um bezerro que mugia."),
"prophets_087": ("Quantas fontes brotaram da rocha que Musa golpeou com o cajado?", ["Doze", "Sete", "Três", "Quarenta"], "«Golpeia a rocha com o teu cajado»: brotaram doze fontes, uma para cada tribo."),
"prophets_088": ("Que alimento fez Allah descer aos Filhos de Israel no deserto?", ["Maná e codornizes", "Arroz e peixe", "Tâmaras e leite", "Pão e azeitonas"], "«Fizemos descer sobre vós o maná e as codornizes.»"),
"prophets_089": ("De que cor era a vaca que Musa mandou os Filhos de Israel sacrificar?", ["Amarelo vivo", "Preta", "Branca", "Vermelha"], "«É uma vaca amarela, de cor viva, que alegra quem a vê.»"),
"prophets_090": ("Quem, do povo de Musa, foi engolido pela terra com a sua casa, pela sua arrogância e riqueza?", ["Qarun", "Haman", "As-Samiri", "Jalut"], "Qarun possuía imensos tesouros; «fizemos a terra engoli-lo a ele e à sua casa»."),
"prophets_091": ("Que metal Allah tornou maleável para Dawud?", ["O ferro", "O ouro", "O cobre", "A prata"], "«E tornámos-lhe o ferro maleável.»"),
"prophets_092": ("O que ensinou Allah a Dawud a fabricar, para proteger as pessoas em combate?", ["Cotas de malha", "Espadas", "Escudos de madeira", "Torres"], "«Ensinámos-lhe a fabricar cotas de malha para vos proteger.»"),
"prophets_093": ("Que gigante matou Dawud em combate, segundo o Alcorão?", ["Jalut (Golias)", "O Faraó", "Haman", "Nimrod"], "«E Dawud matou Jalut, e Allah deu-lhe o reino e a sabedoria.»"),
"prophets_094": ("Como pôs o rei Talut o seu exército à prova antes de enfrentar Jalut?", ["Com um rio: não beber dele, a não ser uma mão-cheia", "Com uma corrida", "Com um jejum de três dias", "Com uma montanha a escalar"], "«Allah vai provar-vos com um rio: quem beber dele não é dos meus, exceto quem tomar uma mão-cheia.»"),
"prophets_095": ("O que fez Allah glorificá-Lo juntamente com Dawud?", ["As montanhas e os pássaros", "Os ventos", "Os génios", "Os peixes"], "«Submetemos as montanhas para Nos glorificarem com Dawud, e também os pássaros.»"),
"prophets_096": ("Que elemento submeteu Allah a Sulayman para o levar aonde quisesse?", ["O vento", "O fogo", "A chuva", "O mar"], "«E a Sulayman, o vento, que soprava com força por ordem sua para a terra abençoada.»"),
"prophets_097": ("Que ave trouxe a Sulayman notícias do reino de Sabá?", ["A poupa", "A águia", "A pomba", "O corvo"], "A poupa voltou e disse: «Soube de algo que tu não sabes, e trago-te de Sabá uma notícia certa»."),
"prophets_098": ("Que pequena criatura avisou as suas companheiras para entrarem em casa quando o exército de Sulayman se aproximava?", ["Uma formiga", "Uma abelha", "Um rato", "Uma aranha"], "Uma formiga disse: «Ó formigas, entrai nas vossas casas, para que Sulayman e as suas tropas não vos esmaguem sem se aperceberem»."),
"prophets_099": ("Com que rapidez foi levado a Sulayman o trono da rainha de Sabá?", ["Antes de o seu olhar voltar a ele", "Num dia", "Em sete dias", "Num mês"], "Aquele que tinha conhecimento do Livro disse: «Trago-to antes de o teu olhar voltar a ti»."),
"prophets_100": ("Segundo o Alcorão, o que fabricavam os génios para Sulayman?", ["Santuários, estátuas e grandes bacias", "Tapetes voadores", "Navios", "Montanhas"], "«Faziam-lhe o que queria: santuários, estátuas, bacias como reservatórios e caldeirões fixos.»"),
"prophets_101": ("Como souberam os génios da morte de Sulayman?", ["Uma criatura da terra roeu o seu cajado e ele caiu", "Um anjo disse-lhes", "A poupa disse-lhes", "Viram-no morrer"], "Só «a criatura da terra» que comia o seu cajado revelou a sua morte; os génios perceberam que não conheciam o oculto."),
"prophets_102": ("Que oração particular fez Sulayman a Allah?", ["Um reino que ninguém depois dele tivesse", "Uma longa vida", "A riqueza de Qarun", "O poder de voar"], "«Senhor meu, perdoa-me e concede-me um reino que ninguém depois de mim possua.»"),
"prophets_103": ("O que ordenou Allah a Ayyub para recuperar a saúde?", ["Bater no chão com o pé: brotou uma fonte fresca", "Jejuar um mês", "Banhar-se no mar", "Subir a uma montanha"], "«Bate com o teu pé: eis uma fonte fresca para te lavares e beberes.»"),
"prophets_104": ("Que súplica fez Yunus na escuridão do ventre do peixe?", ["«Não há deus senão Tu! Glória a Ti, fui dos injustos»", "«Senhor meu, dá-me um reino»", "«Senhor meu, envia-me chuva»", "«Senhor meu, deixa-me ver-Te»"], "«Clamou nas trevas: não há deus senão Tu. Glória a Ti; fui dos injustos.»"),
"prophets_105": ("Que planta fez Allah crescer sobre Yunus depois de o peixe o lançar fora?", ["Uma aboboreira (yaqtin)", "Uma palmeira", "Uma oliveira", "Uma videira"], "«E fizemos crescer sobre ele uma planta de abóbora.»"),
"prophets_106": ("A quantas pessoas foi enviado Yunus, segundo o Alcorão?", ["A cem mil, ou mais", "A mil", "A dez mil", "A doze"], "«E enviámo-lo a cem mil, ou mais.»"),
"prophets_107": ("Que sinal deu Allah a Zakariyya para confirmar a vinda do seu filho?", ["Não falar às pessoas durante três noites, estando são", "Uma estrela cadente", "Chuva no verão", "Um sonho"], "«O teu sinal será não falares às pessoas durante três noites, estando são.»"),
"prophets_108": ("O que diz Allah sobre o nome Yahya?", ["Ninguém antes dele tinha recebido esse nome", "Era o nome do seu avô", "A sua mãe escolheu-o", "Era nome de rei"], "«Anunciamos-te um menino cujo nome será Yahya; não demos esse nome a ninguém antes.»"),
"prophets_109": ("O que concedeu Allah a Yahya ainda em criança?", ["A sabedoria", "Um reino", "Um cavalo", "Um tesouro"], "«Ó Yahya, toma a Escritura com firmeza.» E demos-lhe o discernimento ainda menino."),
"prophets_110": ("O que tinha prometido a mãe de Maryam para o filho que trazia no ventre?", ["Consagrá-lo ao serviço de Allah", "Enviá-lo para o Egito", "Fazê-lo rei", "Confiá-lo a um pastor"], "«Senhor meu, ofereci-Te o que está no meu ventre, consagrado ao Teu serviço.»"),
"prophets_111": ("Que profeta ficou encarregado de Maryam depois do seu nascimento?", ["Zakariyya", "Yahya", "Isa", "Dawud"], "«E confiou-a aos cuidados de Zakariyya», que encontrava junto dela provisão de Allah."),
"prophets_112": ("Segundo o Alcorão, Allah escolheu Maryam acima de quem?", ["Das mulheres dos mundos", "Das rainhas", "Dos anjos", "Dos profetas"], "«Ó Maryam, Allah escolheu-te e purificou-te, e escolheu-te acima das mulheres dos mundos.»"),
"prophets_113": ("O que caiu para Maryam quando sacudiu o tronco da palmeira?", ["Tâmaras frescas e maduras", "Azeitonas", "Figos", "Chuva"], "«Sacode para ti o tronco da palmeira: fará cair sobre ti tâmaras frescas e maduras.»"),
"prophets_114": ("Que palavra usa o Alcorão para Maryam na surata Al-Ma'ida?", ["Veraz (siddiqa)", "Rainha", "Profetisa", "Guerreira"], "«O Messias, filho de Maryam, não era senão um mensageiro… e a sua mãe era uma mulher veraz.»"),
"prophets_115": ("Que título dá o Alcorão a Isa, filho de Maryam?", ["Al-Masih (o Messias)", "Al-Khalil", "Al-Kalim", "As-Siddiq"], "«O seu nome será o Messias, Isa filho de Maryam, distinto neste mundo e no outro.»"),
"prophets_116": ("O que moldou Isa com argila, com a permissão de Allah?", ["A forma de um pássaro, que ganhou vida", "Uma casa", "A estátua de um rei", "Um barco"], "«Moldo para vós com argila a forma de um pássaro, sopro nela e torna-se um pássaro com a permissão de Allah.»"),
"prophets_117": ("Como se chamam os companheiros próximos de Isa, que se declararam «ajudantes de Allah»?", ["Os Hawariyyun (discípulos)", "Os Ansar", "Os Muhajirun", "Os Sahaba"], "«Os discípulos disseram: somos os ajudantes de Allah.»"),
"prophets_118": ("O que pediram os discípulos a Isa, dando o nome à surata Al-Ma'ida?", ["Uma mesa servida descida do céu", "Um livro", "Um reino", "Ouro"], "«Pode o teu Senhor fazer-nos descer uma mesa servida do céu?»"),
"prophets_119": ("O que diz o Alcorão sobre o fim da missão de Isa na terra?", ["Não foi morto nem crucificado: Allah elevou-o para Si", "Morreu de velhice", "Afogou-se", "Foi para o Egito"], "«Não o mataram nem o crucificaram… antes, Allah elevou-o para Si.»"),
"prophets_120": ("Com que nome anunciou Isa um mensageiro que viria depois dele?", ["Ahmad", "Yahya", "Musa", "Ilyas"], "«…anunciando um mensageiro que virá depois de mim, cujo nome é Ahmad.»"),
"prophets_121": ("Que ídolo repreendeu o profeta Ilyas ao seu povo por adorar?", ["Ba'l", "Hubal", "Al-Lat", "Wadd"], "«Invocais Ba'l e abandonais o melhor dos criadores?»"),
"prophets_122": ("Que três profetas menciona o Alcorão juntos «entre os pacientes»?", ["Isma'il, Idris e Dhul-Kifl", "Nuh, Hud e Salih", "Musa, Harun e Yusha'", "Dawud, Sulayman e Ayyub"], "«E Isma'il, Idris e Dhul-Kifl: todos foram dos pacientes.»"),
"prophets_123": ("Que profeta é nomeado na surata Sad juntamente com Isma'il e Dhul-Kifl?", ["Al-Yasa' (Eliseu)", "Yunus", "Lut", "Shu'ayb"], "«E lembra Isma'il, Al-Yasa' e Dhul-Kifl: todos são dos melhores.»"),
"prophets_124": ("Que título dá o Alcorão ao Profeta Muhammad ﷺ no versículo 33:40?", ["O Selo dos Profetas", "O Rei dos árabes", "O Pai dos crentes", "O Amigo de Allah"], "«Muhammad… é o Mensageiro de Allah e o Selo dos Profetas.»"),
"prophets_125": ("Segundo o Alcorão, como foi enviado o Profeta Muhammad ﷺ?", ["Como misericórdia para os mundos", "Como rei", "Como juiz", "Como guerreiro"], "«Não te enviámos senão como misericórdia para os mundos.»"),
"prophets_126": ("Segundo o versículo 33:56, o que fazem Allah e os Seus anjos pelo Profeta ﷺ?", ["Enviam-lhe bênçãos", "Protegem-no dos ventos", "Enviam-lhe chuva", "Observam-no em silêncio"], "«Allah e os Seus anjos abençoam o Profeta. Ó crentes, abençoai-o e saudai-o com a paz!»"),
"prophets_127": ("Como descreve o Alcorão o caráter do Profeta ﷺ na surata Al-Qalam?", ["«És de um caráter imenso»", "«És um grande rei»", "«És o mais rico»", "«És o mais forte»"], "«E, na verdade, és de um caráter imenso.»"),
"prophets_128": ("O que recorda o versículo 3:144 sobre Muhammad ﷺ?", ["Não é senão um mensageiro, e antes dele passaram outros mensageiros", "Nunca morrerá", "É um anjo", "Conhece o futuro"], "«Muhammad não é senão um mensageiro; antes dele passaram outros mensageiros.»"),
"prophets_129": ("Que cinco profetas nomeia juntos o versículo 33:7 para o pacto solene?", ["Nuh, Ibrahim, Musa, Isa e Muhammad ﷺ", "Adam, Nuh, Hud, Salih e Lut", "Dawud, Sulayman, Ayyub, Yunus e Idris", "Isma'il, Ishaq, Ya'qub, Yusuf e Musa"], "«Tomámos dos profetas o seu pacto: de ti, de Nuh, Ibrahim, Musa e Isa filho de Maryam.»"),
"prophets_130": ("Segundo um hadith de al-Bukhari, que ofício exerceu todo profeta?", ["Pastor", "Carpinteiro", "Ferreiro", "Mercador"], "«Allah não enviou nenhum profeta que não tivesse guardado ovelhas», e o Profeta ﷺ guardou-as para o povo de Meca."),
"prophets_131": ("Segundo um hadith de Muslim, que profeta trabalhou como carpinteiro?", ["Zakariyya", "Nuh", "Idris", "Yusuf"], "O Profeta ﷺ disse: «Zakariyya era carpinteiro»."),
"prophets_132": ("De que profeta disse o Profeta ﷺ ser «o mais próximo das pessoas», neste mundo e no outro?", ["Isa filho de Maryam", "Musa", "Ibrahim", "Nuh"], "«Sou o mais próximo de todas as pessoas de Isa filho de Maryam neste mundo e no outro; os profetas são irmãos.»"),
"prophets_133": ("Quantas suratas do Alcorão têm o nome de um profeta?", ["Seis", "Duas", "Doze", "Vinte e cinco"], "Yunus (10), Hud (11), Yusuf (12), Ibrahim (14), Muhammad (47) e Nuh (71)."),
"prophets_134": ("Com que três palavras descreve o Alcorão Ibrahim no versículo 11:75?", ["Indulgente, terno de coração, sempre voltado para Allah", "Rico, poderoso, sábio", "Forte, rápido, corajoso", "Rei, juiz, guerreiro"], "«Na verdade, Ibrahim era indulgente, compassivo e sempre voltado para Allah.»"),
"prophets_135": ("O que repreendeu Shu'ayb ao seu povo, além da idolatria?", ["Enganar nos pesos e nas medidas", "Não rezar", "Viajar de noite", "Comer peixe"], "«Dai a medida e o peso completos, e não priveis as pessoas do que lhes é devido.»"),
"prophets_136": ("O que atingiu o povo de Shu'ayb depois de rejeitar a sua mensagem?", ["Um terramoto", "Um dilúvio", "Uma chuva de fogo", "Um bando de pássaros"], "«O terramoto atingiu-os, e amanheceram nas suas casas caídos de bruços.»"),
"prophets_137": ("Que notícia deram os anjos a Ibrahim depois de acalmarem o seu temor?", ["Que tinham sido enviados ao povo de Lut", "Que vinha um dilúvio", "Que a Ka'ba seria destruída", "Que o Faraó se afogaria"], "«Não temas: fomos enviados ao povo de Lut.»"),
"prophets_138": ("O que pediu Ibrahim para si e para os seus descendentes no versículo 14:40?", ["Serem dos que cumprem a oração", "Serem reis", "Serem ricos", "Viverem muito"], "«Senhor meu, faz que eu cumpra a oração, e também a minha descendência.»"),
"prophets_139": ("No fim da história de Yusuf, quem fez ele subir ao trono antes de todos se prostrarem diante dele?", ["Os seus pais", "O rei", "Os seus irmãos", "O seu filho"], "«Fez subir os seus pais ao trono, e caíram prostrados diante dele»: o sonho de infância cumpriu-se."),
"prophets_140": ("Porque queriam os irmãos de Yusuf livrar-se dele?", ["Por inveja: o pai amava-o mais", "Tinha roubado", "Recusava-se a trabalhar", "Estava doente"], "«Yusuf e o seu irmão são mais queridos para o nosso pai do que nós… Matai Yusuf ou expulsai-o para alguma terra.»"),
"prophets_141": ("O que trouxeram os irmãos de Yusuf ao pai para o fazer crer que um lobo o tinha devorado?", ["A sua camisa manchada de sangue falso", "As suas sandálias", "O seu cajado", "O dente de um lobo"], "«Trouxeram a sua camisa com sangue falso»; Ya'qub respondeu: «Paciência, é o mais belo»."),
"prophets_142": ("O que prometeu Allah à mãe de Musa ao inspirá-la a pô-lo no rio?", ["Devolver-lho e fazer dele um mensageiro", "Dar-lhe outro filho", "Fazê-la rainha", "Enviar chuva"], "«Não temas nem te aflijas: devolver-to-emos e faremos dele um dos mensageiros.»"),
"prophets_143": ("Com que golpeou Musa o mar para que se abrisse?", ["Com o seu cajado", "Com a mão", "Com uma pedra", "Com a espada"], "«Golpeia o mar com o teu cajado»: abriu-se, e cada lado era como uma grande montanha."),
"prophets_144": ("O que foi a primeira coisa que Allah disse a Musa ao dirigir-se a ele?", ["«Eu sou Allah, não há deus senão Eu: adora-Me e cumpre a oração»", "«Vai pescar»", "«Constrói uma arca»", "«Volta para o Faraó»"], "«Na verdade, Eu sou Allah; não há deus senão Eu, adora-Me e cumpre a oração para te lembrares de Mim.»"),
"prophets_145": ("Como disse Allah a Musa e Harun que falassem ao Faraó?", ["Com palavras suaves", "Com raiva", "Aos gritos", "Em silêncio"], "«Ide ao Faraó… e falai-lhe com palavras suaves; talvez reflita ou tema.»"),
"prophets_146": ("O que disse Musa ao seu jovem servo no início da viagem até à confluência dos dois mares?", ["Que não pararia até chegar à confluência dos dois mares", "Que queria voltar para casa", "Que tinha medo", "Que procurava ouro"], "«Não desistirei até chegar à confluência dos dois mares, ainda que caminhe durante muito tempo.»"),
"prophets_147": ("Qual destas coisas fez o servo sábio diante de Musa, que não a compreendeu no momento?", ["Fez um buraco num barco", "Construiu uma ponte", "Acendeu um fogo", "Plantou uma árvore"], "Furou o barco, depois matou um rapaz e endireitou um muro; depois explicou a Musa cada ato."),
"prophets_148": ("Quais foram as primeiras palavras de Isa, ainda no berço?", ["«Sou o servo de Allah; Ele deu-me a Escritura e fez de mim um profeta»", "«Sou o filho de Deus»", "«Sou um rei»", "«Tenho fome»"], "«Disse: sou o servo de Allah. Ele deu-me a Escritura e fez de mim um profeta.»"),
"prophets_149": ("O que disseram Adam e a sua esposa a Allah depois de comerem da árvore?", ["«Senhor nosso, fomos injustos connosco mesmos; se não nos perdoares, estaremos perdidos»", "«Não foi culpa nossa»", "«Foi culpa da árvore»", "Não disseram nada"], "«Senhor nosso, fomos injustos connosco mesmos, e se não nos perdoares e não tiveres misericórdia de nós, seremos dos perdedores.»"),
"prophets_150": ("Que missão deu Allah a Nuh junto do seu povo, no primeiro versículo da surata Nuh?", ["Avisá-los antes que lhes chegasse um castigo doloroso", "Construir uma cidade", "Ensiná-los a pescar", "Fazê-los reis"], "«Enviámos Nuh ao seu povo: avisa o teu povo antes que lhe chegue um castigo doloroso.»"),
}
